def parse_record(raw):
    parts = [piece.strip() for piece in raw.split(";")]
    if len(parts) not in (4, 5):
        return {"ok": False, "error": "fields", "raw": raw}
    day = "main"
    if len(parts) == 5:
        day = parts[0]
        if day not in ("mon", "tue", "wed", "thu", "fri", "sat", "sun"):
            return {"ok": False, "error": "day", "raw": raw}
        parts = parts[1:]
    start_s, dur_s, room, title = parts
    if ":" in start_s:
        hour, sep, minute = start_s.partition(":")
        if not hour.isdigit() or not minute.isdigit():
            return {"ok": False, "error": "start", "raw": raw}
    else:
        if len(start_s) != 4 or not start_s.isdigit():
            return {"ok": False, "error": "start", "raw": raw}
        hour, minute = start_s[:2], start_s[2:]
    start = int(hour) * 60 + int(minute)
    if int(minute) > 59 or start > 1439:
        return {"ok": False, "error": "start", "raw": raw}
    if dur_s.isdigit():
        dur = int(dur_s)
    else:
        hours, sep, mins = dur_s.partition("h")
        if not sep or not hours.isdigit():
            return {"ok": False, "error": "duration", "raw": raw}
        if mins == "":
            dur = int(hours) * 60
        elif len(mins) == 2 and mins.isdigit() and int(mins) <= 59:
            dur = int(hours) * 60 + int(mins)
        else:
            return {"ok": False, "error": "duration", "raw": raw}
    if dur < 15 or dur > 240:
        return {"ok": False, "error": "duration", "raw": raw}
    if room == "" or title == "":
        return {"ok": False, "error": "empty", "raw": raw}
    end = start + dur
    if end > 1440:
        end = 1440
        dur = end - start
        if dur < 15:
            return {"ok": False, "error": "duration", "raw": raw}
    priority = "normal"
    if title.startswith("#"):
        priority = "high"
        title = title[1:].strip()
        if title == "":
            return {"ok": False, "error": "empty", "raw": raw}
    return {"ok": True, "day": day, "start": start, "dur": dur,
            "end": end, "room": room, "title": title,
            "priority": priority}

